  "it.f_mon": "टैक्स कम होखे पर ब्याज के महीना",
  "it.f_mon_h": "साल के बाद वाला 1 April से रिटर्न प्रोसेस होखे के दिन ले। 4 = 31 July ले फाइल कइल रिटर्न।",
  "it.m_senior": "60 भा ओकरा से बेसी उमिर के निवासी जेकरा कवनो बिज़नेस भा प्रोफेशनल आमदनी नइखे, एडवांस टैक्स ना देला (section 403(3))। बाकी टैक्स रिटर्न फाइल करत घरी दीं।",
  "it.m_below": "TDS के बाद टैक्स {n} बा, ₹10,000 से कम, एह से कवनो एडवांस टैक्स ना लागी (section 404)। बाकी टैक्स रिटर्न फाइल करत घरी दीं।",
  "it.m_pres": "प्रिज़म्प्टिव स्कीम में पूरा एडवांस टैक्स 15 March भा ओकरा से पहिले दिहल जाला (section 408(2))।",
  "it.m_sur": "राउर आमदनी ₹50 लाख से ऊपर बा: सरचार्ज लिखीं, एहिजा ई ना निकालल जाला।",
  "it.m_past": "ई साल खतम हो गइल। 31 March के बाद दिहल एडवांस टैक्स एह साल के एडवांस टैक्स ना गिनाला; नीचे के ब्याज बतावेला कि कमी के का लागत बा।",
  "it.m_season": "अंदाज़ा अबहीं ले के मुनाफ़ा के सीधा पूरा साल ले बढ़ा देला। अगर राउर बिज़नेस मौसमी बा, त साल के आपन आँकड़ा लिखीं।",
