  "it.basis": "ई आँकड़ा कवना आधार पर बा ({d} के)",
  "it.b1": "रेट ({d} के), टैक्स साल 2026-27: नया रिजीम ₹4 लाख ले शून्य, ₹8 लाख ले 5%, ₹12 लाख ले 10%, ₹16 लाख ले 15%, ₹20 लाख ले 20%, ₹24 लाख ले 25%, ओकरा से ऊपर 30%; रिबेट अइसन कि ₹12 लाख ले के आमदनी पर टैक्स ना लागे, ओकरा ठीक ऊपर मार्जिनल रिलीफ़ के साथे; सैलरी पर स्टैंडर्ड डिडक्शन ₹75,000। पुरान रिजीम: ₹2.5 लाख ले शून्य (60 पर ₹3 लाख, 80 पर ₹5 लाख), ₹5 लाख ले 5%, ₹10 लाख ले 20%, ओकरा से ऊपर 30%; ₹5 लाख ले रिबेट ₹12,500; स्टैंडर्ड डिडक्शन ₹50,000। ई ओही रेट ह जवन सैलरी स्लिप टूल पहिले से इस्तेमाल करेला; एह बिल्ड में Finance Act से फेर से ना पढ़ल गइल, एह से जाँच लीं।",
  "it.b2": "एडवांस टैक्स (Income-tax Act 2025, sections 403 से 408): तब लागेला जब TDS के बाद टैक्स ₹10,000 भा बेसी होखे; 15 June ले 15%, 15 September ले 45%, 15 December ले 75%, 15 March ले सब; प्रिज़म्प्टिव टैक्सपेयर सब 15 March ले देला; 31 March ले के पेमेंट साल में गिनाला; 60 भा बेसी उमिर के निवासी जेकरा बिज़नेस आमदनी नइखे, छूट में बा।",
  "it.b3": "ब्याज: section 424 (पुरान 234B) कमी पर हर महीना भा महीना के हिस्सा पर 1% बा जब टैक्स के 90% से कम दिहल गइल; section 425 (पुरान 234C) पहिला तीन किस्त में से हर के कमी पर 3% (कुछ ना अगर 15 June ले 12% आ 15 September ले 36% दिहल गइल) आ March के कमी पर 1% बा।",
  "it.b4": "ऊपर के सेक्शन 15 Nov 2026 के Income Tax Department के वेबसाइट (incometaxindia.gov.in) पर आधिकारिक टेक्स्ट से शब्द-शब्द जाँचल गइल। छापल Act मानल जाई।",
  "it.b5": "खाता-बही के मुनाफ़ा टैक्स वाला मुनाफ़ा ना ह: Act के तहत डेप्रिसिएशन, नामंज़ूर खर्चा आ प्रिज़म्प्टिव नियम एकरा के बदल देला। ई प्लान आ डेटा शीट अपना अकाउंटेंट के दीं।",
  "it.b6": "ना निकालल जाला: सरचार्ज, खास रेट वाला कैपिटल गेन, बिदेसी टैक्स राहत, नाबालिग के आमदनी पर टैक्स, आ देरी से फाइल करे पर ब्याज।",
  "it.b7": "कुछुओ फाइल ना होला आ राउर खाता-बही में कुछुओ ना जुड़ेला।",
  "it.itr_h": "कुछ सवाल के जवाब दीं आ देखीं कि कवन रिटर्न फ़ॉर्म ठीक बा, काहे, आ कवन कागज तइयार राखे के बा।",
