  "it.q_crypto": "हम क्रिप्टो जइसन वर्चुअल डिजिटल एसेट बेचले बानी",
  "it.formd_ITR-1": "सैलरी भा पेंशन, दू मकान ले, आ ब्याज जइसन दोसर स्रोत वाला, आ ₹50 लाख ले कुल आमदनी वाला निवासी आदमी खातिर।",
  "it.formd_ITR-2": "बिना बिज़नेस भा प्रोफेशन आमदनी वाला आदमी भा HUF खातिर, जेकरा कैपिटल गेन, ₹50 लाख से ऊपर आमदनी, दू से बेसी मकान, बिदेसी संपत्ति भा आमदनी बा, भा जे ITR-1 में ना बइठे।",
  "it.formd_ITR-3": "अइसन आदमी भा HUF खातिर जेकरा प्रिज़म्प्टिव स्कीम से बाहर के बिज़नेस भा प्रोफेशन आमदनी बा, फर्म के पार्टनर, भा जे ITR-4 में ना बइठे।",
  "it.formd_ITR-4": "प्रिज़म्प्टिव बिज़नेस आमदनी, ₹50 लाख ले कुल आमदनी, सैलरी भा पेंशन, दू मकान ले आ दोसर स्रोत वाला निवासी आदमी भा HUF खातिर।",
  "it.formd_ITR-5": "फर्म, LLP, एसोसिएशन ऑफ़ पर्सन्स आ बॉडी ऑफ़ इंडिविजुअल्स खातिर।",
  "it.formd_ITR-6": "धरम-करम भा परोपकार खातिर छूट माँगे वाला के छोड़ के बाकी कंपनी खातिर।",
  "it.formd_ITR-7": "ट्रस्ट, संस्था, राजनीतिक दल आ अइसने लोग खातिर।",
  "it.w_company": "कंपनी ITR-6 फाइल करेले।",
