  "it.w_other": "ट्रस्ट, संस्था आ राजनीतिक दल ITR-7 फाइल करेला।",
  "it.w_partner": "जवना फर्म में रउआ पार्टनर बानी, ओकरा से मिलल पारिश्रमिक भा ब्याज बिज़नेस आमदनी ह, ITR-3 में देखावल जाला।",
  "it.w_business": "रउआ बिज़नेस भा प्रोफेशनल मुनाफ़ा खाता-बही से निकालीले, एह खातिर ITR-3 चाहीं।",
  "it.w_presnot": "प्रिज़म्प्टिव फ़ॉर्म आदमी आ HUF खातिर बा।",
  "it.w_nonres": "जे निवासी नइखे, ऊ ITR-1 भा ITR-4 इस्तेमाल ना कर सकेला।",
  "it.w_over50": "₹50 लाख से ऊपर कुल आमदनी पर ITR-1 आ ITR-4 ना चली।",
  "it.w_capgain": "छोट लिस्टेड-शेयर सीमा से बाहर के कैपिटल गेन खातिर ITR-2 भा ITR-3 चाहीं।",
  "it.w_houses": "दू से बेसी मकान होखे पर ITR-1 आ ITR-4 ना चली।",
  "it.w_foreign": "बिदेसी संपत्ति भा बिदेसी आमदनी खातिर ITR-2 भा ITR-3 चाहीं।",
  "it.w_director": "कंपनी के डायरेक्टर ITR-1 भा ITR-4 इस्तेमाल ना कर सकेला।",
  "it.w_unlisted": "अनलिस्टेड शेयर होखे पर ITR-1 आ ITR-4 ना चली।",
  "it.w_agri": "₹5,000 से ऊपर खेती के आमदनी पर ITR-1 आ ITR-4 ना चली।",
  "it.w_loss": "आगे ले जाए भा समायोजन करे वाला घाटा खातिर ITR-2 भा ITR-3 चाहीं।",
  "it.w_esop": "मालिक के शेयर पर टालल टैक्स खातिर ITR-2 भा ITR-3 चाहीं।",
  "it.w_crypto": "वर्चुअल डिजिटल एसेट से आमदनी खातिर ITR-2 भा ITR-3 चाहीं।",
  "it.w_huf": "ITR-1 खाली आदमी खातिर बा; बिना बिज़नेस आमदनी वाला HUF ITR-2 फाइल करेला।",
  "it.w_pres2": "राउर दोसर जवाब से ITR-4 ना चली, एह से बिज़नेस आमदनी ITR-3 में जाई।",
  "it.w_pres": "प्रिज़म्प्टिव बिज़नेस आमदनी आ साधारण दोसर आमदनी खातिर ITR-4 ठीक बा।",
  "it.w_simple": "खाली सैलरी, मकान आ ब्याज, सीमा के भीतर, त ITR-1 ठीक बा।",
  "it.n_forms": "शर्त 31 March 2026 के खतम भइल साल खातिर अधिसूचित रिटर्न के हिसाब से बा (टैक्स पोर्टल के मुताबिक, ITR-1 आ ITR-4 में अब दू मकान ले चलेला)। टैक्स साल 2026-27 के रिटर्न Income-tax Rules, 2026 में अबहीं अधिसूचित होखे के बाकी बा: फाइल करे से पहिले फ़ॉर्म में दिहल लिस्ट पढ़ लीं कि के एकरा के इस्तेमाल ना कर सकेला।",
  "it.n_ltcg": "लिस्टेड शेयर भा इक्विटी फंड पर छोट लंबा समय वाला गेन कुछ साल ITR-1 आ ITR-4 में चलत रहे; 2026-27 खातिर ई पक्का नइखे, एह से ITR-2 सुरक्षित बा आ फ़ॉर्म के आपन लिस्ट मानल जाई।",
  "it.n_ae": "Section 44AE (माल ढोवे वाला गाड़ी) के आपन शर्त बा; प्रिज़म्प्टिव फ़ॉर्म इस्तेमाल करे से पहिले ओकरा के जाँच लीं।",
  "it.n_tax": "प्रिज़म्प्टिव रेट से कम मुनाफ़ा बतावे खातिर खाता-बही चाहीं आ ऑडिट भी लाग सकेला: तब रिटर्न ITR-3 होला।",
  "it.d_pan": "PAN, Aadhaar से जुड़ल",
  "it.d_aadhaar": "Aadhaar नंबर आ ओकरा से जुड़ल मोबाइल नंबर, OTP खातिर",
  "it.d_ais": "Annual Information Statement आ Form 26AS: ओहिजा देखावल TDS अपना रिकॉर्ड से मिलाईं",
  "it.d_form16": "मालिक से Form 16 आ सैलरी स्लिप",
