  "ca.mk": "हमरा अकाउंटेंट खातिर फ़ाइल बनाईं (खाली पढ़े खातिर)",
  "ca.t": "हमरा अकाउंटेंट खातिर फ़ाइल",
  "ca.intro": "एगो बिज़नेस आ अवधि के एके खाली-पढ़े वाला फ़ाइल (.nsca) में बाँध देला। एकरा के अपना अकाउंटेंट के WhatsApp भा ईमेल से भेजीं। ऊ एकरा के ca.niveshsahayak.in पर खोलेलन, खाता-बही पढ़ेलन, सवाल जोड़ेलन आ रउआ के टिप्पणी वापस भेजेलन।",
  "ca.notlive": "ई फ़ाइल सौंपल ह, लाइव साझा लॉगिन ना। राउर अकाउंटेंट खाता-बही ओइसहीं देखेलन जइसन फ़ाइल बनावत घरी रहे। लाइव लॉगिन खातिर अइसन सर्वर चाहीं जे राउर खाता-बही राखे, आ Nivesh Sahayak लगे कवनो सर्वर नइखे: राउर खाता-बही रउआ डिवाइस पर रहेला। नया एंट्री खातिर नया फ़ाइल बनाईं।",
  "ca.what": "का-का जाला",
  "ca.earlier": "पहिला तारीख से पहिले के एंट्री भी (शुरू के बैलेंस आ एजिंग खातिर ज़रूरी)",
  "ca.items": "खरीद आ बिक्री रेट के साथे आइटम लिस्ट (स्टॉक खातिर ज़रूरी)",
  "ca.extra": "खाली टिक कइला पर",
  "ca.extrah": "टिक ना कइला पर छोड़ दिहल जाला। तस्वीर (लोगो, दस्तखत), राउर PIN आ बैकअप सेटिंग कबो शामिल ना होला।",
