  "ca.codeh": "ई कोड अपना मैसेज में भेजीं, भा फ़ोन पर पढ़ के सुनाईं। राउर अकाउंटेंट एकरा के फ़ाइल में देखावल कोड से मिलावेलन, ताकि रास्ता में बदलल फ़ाइल पकड़ में आ जाव।",
