  "ca.how": "फ़ाइल WhatsApp भा ई-मेल से अटैचमेंट के रूप में भेजीं। अगर WhatsApp नाम के आखिर में .nsca देखावे, त नाम मत बदलीं।",
  "ca.cT": "CA के टिप्पणी",
  "ca.cIntro": "राउर अकाउंटेंट सवाल आ टिप्पणी के एगो छोट फ़ाइल (.nsca-comments) वापस भेजेलन। हर सवाल ओकरा एंट्री के बगल में देखे खातिर एकरा के एहिजा लोड करीं। जवाब दीं, बंद मार्क करीं, आ वापस भेजे खातिर फ़ाइल फेर से सेव करीं।",
