  "ca.general": "आम टिप्पणी",
  "cv.h1": "अकाउंटेंट व्यूअर: राउर क्लाइंट के भेजल खाता-बही फ़ाइल खोलीं",
  "cv.intro": "राउर क्लाइंट कवनो अवधि के आपन खाता-बही एगो फ़ाइल में बाँध के रउआ के WhatsApp भा ईमेल से भेजेलन। एहिजा खोल के पढ़ीं: बकाया, पार्टी, लेजर, डे बुक, GST हिसाब, फाइनल अकाउंट आ हर दस्तावेज़। खोजीं आ फ़िल्टर करीं, कवनो एंट्री पर सवाल पूछीं, आ अपना टिप्पणी छोट फ़ाइल में वापस भेजीं। मुफ़्त, बिना लॉगिन, आ कुछुओ अपलोड ना होला: फ़ाइल राउर ब्राउज़र के भीतर पढ़ल जाला।",
