  "cv.fin": "फाइनल अकाउंट",
  "cv.gst": "GST हिसाब",
  "cv.cT": "सवाल आ टिप्पणी",
  "cv.how.h": "ई कइसे काम करेला",
  "cv.how.1": "राउर क्लाइंट Nivesh Sahayak खोलेलन, “हमार डेटा” में जालन, “अपना अकाउंटेंट के भेजीं” में एगो बिज़नेस आ अवधि खातिर \"हमरा अकाउंटेंट खातिर फ़ाइल बनाईं\" चुनेलन।",
  "cv.how.2": "ऊ रउआ के फ़ाइल (आखिर में .nsca) आ एही मैसेज में एगो छोट जाँच कोड भेजेलन।",
  "cv.how.3": "रउआ फ़ाइल एह पेज पर खोलीं। पेज बतावेला कि फ़ाइल बिना बदलाव के बा कि ना, आ मिलावे खातिर क्लाइंट के दिहल जाँच कोड लिखे देला।",
  "cv.how.4": "खाता-बही पढ़ीं, खोजीं, आ कवनो दस्तावेज़, डे बुक एंट्री भा स्क्रीन पर \"सवाल भा टिप्पणी जोड़ीं\" दबाईं। जवन लिखीं, सब एही ब्राउज़र में रहेला।",
  "cv.how.5": "काम हो गइला पर \"सवाल आ टिप्पणी\" खोलीं आ छोट .nsca-comments फ़ाइल वापस भेजीं। राउर क्लाइंट एकरा के लोड क के हर सवाल एंट्री के बगल में देखेलन। ऊ जवाब दे सकेलन, आ रउआ जवाब एहिजा लोड क सकेनी।",
  "cv.live.h": "फ़ाइल सौंपल, लाइव लॉगिन ना",
  "cv.live.p": "ई फ़ाइल सौंपल ह। रउआ अपना क्लाइंट के खाता में लॉगिन ना करीं आ ऊ बाद में जवन बदलाव करेलन, ऊ ना देखीं। लाइव साझा लॉगिन खातिर अइसन सर्वर चाहीं जे खाता-बही राखे, आ Nivesh Sahayak लगे कवनो सर्वर नइखे: खाता-बही राउर क्लाइंट के डिवाइस पर रहेला। नया अवधि खातिर भा सुधार के बाद अपना क्लाइंट से नया फ़ाइल माँगीं।",
  "cv.safe.h": "फ़ाइल में का बा, आ का नइखे",
  "cv.safe.p": "राउर क्लाइंट टिक करेलन कि का जाई। आम तौर पर फ़ाइल में एगो बिज़नेस के एंट्री, पार्टी आ आइटम अवधि के आखिर ले रहेला। कोटेशन आ ऑर्डर, सैलरी आ स्टाफ रिकॉर्ड, फ़ोन नंबर आ ई-मेल पता, आ बिज़नेस के बैंक खाता के डिटेल तब ले छोड़ दिहल जाला जब ले राउर क्लाइंट टिक ना करस। तस्वीर, PIN आ बैकअप सेटिंग कबो शामिल ना होला। फ़ाइल में चेकसम रहेला, एह से एकरा में कवनो बदलाव एह पेज पर देखाई देला। चेकसम ओकरा के ना रोक सकेला जे फ़ाइल बदल के चेकसम फेर से निकाल देव, एह से जाँच कोड के ओह कोड से मिलाईं जवन राउर क्लाइंट अलग से भेजले बाड़न।",
  "cv.readonly": "ई एगो फ़ाइल के खाली-पढ़े वाला व्यू ह: एहिजा कुछुओ बदलल भा सेव ना हो सकेला।",
  "cv.notfile": "ई Nivesh Sahayak अकाउंटेंट फ़ाइल (.nsca) ना ह।",
  "cv.iscomments": "ई कमेंट फ़ाइल ह। पहिले खाता-बही फ़ाइल (.nsca) खोलीं, फेर \"सवाल आ टिप्पणी\" से कमेंट लोड करीं।",
  "cv.newer": "ई फ़ाइल नया वर्ज़न से बनल बा। ई पेज फेर से लोड क के कोशिश करीं।",
