  "hm.rm.icsp": "अगिला 60 दिन के एगो कैलेंडर फ़ाइल बनावेला: बिल के आखिरी तारीख आ टैक्स के तारीख। अपना कैलेंडर में जोड़े खातिर फ़ोन पर खोलीं, जवन एक दिन पहिले अपने बाजेला, ई App बंद रहला पर भी।",
