  "hm.rm.pay": "दीं",
  "hm.rm.lim": "ब्राउज़र का ना कर सकेला",
  "hm.rm.l1": "वेब पेज बंद रहला पर ना चल सकेला, आ एह App के पीछे कवनो सर्वर नइखे जे रउआ के पुश मैसेज भेजे। एह से App के याद तबे देखाई देला जब रउआ App खोलीं।",
  "hm.rm.l2": "सब कुछ राउर डिवाइस पर निकलेला, एह से बिना इंटरनेट के चलेला। राउर बिज़नेस के बारे में कुछुओ कतहीं ना भेजाला।",
  "hm.rm.l3": "जवन तारीख छूटे के ना चाहीं, ओकरा खातिर कैलेंडर फ़ाइल इस्तेमाल करीं: राउर फ़ोन के कैलेंडर अपने बाजेला। ई आज के तस्वीर ह, एह से नया बिल दर्ज कइला के बाद नया फ़ाइल बनाईं।",
  "hm.rm.l4": "इंस्टॉल कइल App पर, जहाँ फ़ोन अनुमति देला, ओकरा आइकन पर नंबर बतावेला कि केतना जरूरी चीज़ बा।",
