  "sfd.limits": "Chrome and Edge on a computer only. If two people change the same thing at the same moment, both versions are kept and listed above. A PIN is a lock for daily use, not strong security: anyone who can open the folder in Windows can read it.",
  "sfd.roles.t": "Who may do what",
  "sfd.roles.p": "Set a PIN for the owner. Then add staff, each with their own PIN. Staff can make bills and parties but cannot delete, change settings, see the final accounts or take backups.",
